#!/usr/bin/env bash
# Print the three most frequent client IP addresses, resolving equal counts by
# their first occurrence in access.log.
set -euo pipefail

awk '
    NF {
        ip = $1
        if (!(ip in first_seen))
            first_seen[ip] = ++sequence
        count[ip]++
    }
    END {
        for (ip in count)
            printf "%d\t%d\t%s\n", count[ip], first_seen[ip], ip
    }
' access.log |
    sort -t $'\t' -k1,1nr -k2,2n |
    head -n 3 |
    cut -f3
